+let W=0,H=0,dpr=1,state='title',last=0,elapsed=0,spawnTimer=0,shake=0,toastTimer=0;
+const keys=new Set(),enemies=[],shots=[],gems=[],particles=[],decor=[];
+const player={x:0,y:0,r:14,hp:3,maxHp:3,speed:210,ifr:0,level:1,xp:0,next:5,damage:1,rate:.48,range:470,power:1,magnet:110,weapon:0};
+const cam={x:0,y:0};let aim=null,joy={x:0,y:0},fireHeld=false,score=0;
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+function resize(){dpr=Math.min(devicePixelRatio||1,2);W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
+addEventListener('resize',resize);resize();
+function reset(){elapsed=0;spawnTimer=.5;score=0;enemies.length=shots.length=gems.length=particles.length=0;player.x=player.y=0;player.hp=3;player.maxHp=3;player.speed=210;player.ifr=0;player.level=1;player.xp=0;player.next=5;player.damage=1;player.rate=.48;player.range=470;player.power=1;player.magnet=110;player.weapon=0;cam.x=cam.y=0;updateHud()}
+function updateHud(){ui.hp.textContent='♥ '.repeat(Math.max(0,player.hp)).trim()+(player.hp<player.maxHp?' ♡'.repeat(player.maxHp-player.hp):'');ui.clock.textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;ui.lvl.textContent=String(player.level).padStart(2,'0');ui.xp.style.width=`${Math.min(100,player.xp/player.next*100)}%`}
+function worldPoint(x,y){return{x:x-cam.x+W/2,y:y-cam.y+H/2}}
