function update(dt){if(state!=='playing')return;elapsed+=dt;player.ifr=Math.max(0,player.ifr-dt);const kx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0)+joy.x,ky=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0)+joy.y,kl=Math.hypot(kx,ky)||1;player.x+=kx/kl*player.speed*dt;player.y+=ky/kl*player.speed*dt;cam.x+=(player.x-cam.x)*Math.min(1,dt*7);cam.y+=(player.y-cam.y)*Math.min(1,dt*7);
spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy();spawnTimer=Math.max(.18,.85-elapsed*.002)+Math.random()*.38}
player.weapon-=dt;if(player.weapon<=0){fire();player.weapon=player.rate}
for(let i=enemies.length-1;i>=0;i--){const e=enemies[i],dx=player.x-e.x,dy=player.y-e.y,l=Math.hypot(dx,dy)||1;e.phase+=dt*4;e.x+=dx/l*e.speed*dt+Math.sin(e.phase)*8*dt;e.y+=dy/l*e.speed*dt+Math.cos(e.phase*.8)*8*dt;if(dist(e,player)<e.r+player.r-2)damagePlayer();if(e.hit>0)e.hit-=dt}
for(let i=shots.length-1;i>=0;i--){const s=shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;let dead=s.life<=0;for(let j=enemies.length-1;j>=0&&!dead;j--){const e=enemies[j];if(Math.hypot(s.x-e.x,s.y-e.y)<s.r+e.r){e.hp-=s.damage;e.hit=.12;burst(s.x,s.y,s.color,3,60);if(e.hp<=0){dropGem(e);enemies.splice(j,1);score++}dead=true}}if(dead)shots.splice(i,1)}
for(let i=gems.length-1;i>=0;i--){const g=gems[i],d=dist(g,player);if(d<player.magnet){const pull=(1-d/player.magnet)*520+90;g.x+=(player.x-g.x)/(d||1)*pull*dt;g.y+=(player.y-g.y)/(d||1)*pull*dt}if(d<player.r+g.r+5){collectXp(g.value);gems.splice(i,1);burst(player.x,player.y,'#a4f5d6',4,60)}}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1)}
if(Math.floor(elapsed)!==Math.floor(elapsed-dt))updateHud();if(elapsed>=180)finish(true);shake=Math.max(0,shake-dt*28)}

