// Soft lantern motes
for(let i=0;i<18;i++){const x=((i*193+elapsed*8)% (W+30))-15,y=(i*97+Math.sin(elapsed*.7+i)*50+H*.23)%H;ctx.globalAlpha=.23;circle(x,y,1.5,'#e5d78c')}ctx.globalAlpha=1}
function drawPlayer(){const p=worldPoint(player.x,player.y);ctx.save();ctx.translate(p.x,p.y);if(player.ifr>0&&Math.floor(player.ifr*14)%2)ctx.globalAlpha=.35;ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(0,10,15,7,0,0,Math.PI*2);ctx.fill();circle(0,1,13,'#6cd4bd');circle(0,-7,9,'#ffd7a0');ctx.fillStyle='#ef765e';ctx.beginPath();ctx.moveTo(-12,-11);ctx.quadraticCurveTo(-1,-18,11,-11);ctx.lineTo(13,-8);ctx.quadraticCurveTo(0,-10,-13,-7);ctx.fill();ctx.fillStyle='#172c35';circle(-3,-7,1.2,'#172c35');circle(3,-7,1.2,'#172c35');ctx.strokeStyle='#c56453';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,-4,3,.2,Math.PI-.2);ctx.stroke();ctx.strokeStyle='#ffda75';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(7,4);ctx.lineTo(15,-9);ctx.stroke();circle(16,-11,3,'#fff0a5');ctx.restore()}
