function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawWorld();for(const g of gems){const p=worldPoint(g.x,g.y),r=g.r+Math.sin(elapsed*5+g.wob)*1.5;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.PI/4);ctx.fillStyle='#a5f2d4';ctx.shadowColor='#9af5d1';ctx.shadowBlur=12;ctx.fillRect(-r/2,-r/2,r,r);ctx.restore()}for(const s of shots){const p=worldPoint(s.x,s.y);ctx.shadowColor=s.color;ctx.shadowBlur=15;circle(p.x,p.y,s.r,s.color);ctx.shadowBlur=0}for(const e of enemies)drawEnemy(e);drawPlayer();for(const q of particles){const p=worldPoint(q.x,q.y);ctx.globalAlpha=Math.max(0,q.life/q.max);circle(p.x,p.y,q.r,q.color)}ctx.globalAlpha=1;ctx.restore();requestAnimationFrame(frame)}

